// План specs/modals.md, 1.2 (кейс MD-02). Admin. Только чтение: текст не вводится, клиент не создаётся, окно закрывается Esc. @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#08737d6c)', () => {
  for (const device of DEVICES) {
    test(`Create Client with AI window is opaque over a dimmed page #08737d6c ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: форма нового клиента → Create with AI
      await page.goto('/CustomerForm?action=new');
      await page.getByRole('button', { name: 'Create with AI' }).filter({ visible: true }).first().click();

      // Шаг 2: окно «Generate Client from Description» непрозрачное, страница затемнена
      const dialog = page.getByRole('dialog', { name: 'Generate Client from Description' });
      await expectOpaqueModalOverDimmedPage(page, dialog);

      // Шаг 3: Esc
      await closeWithEsc(page, dialog);
    });
  }
});
